import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";

const states = [
  "Andhra Pradesh", "Arunachal Pradesh", "Assam", "Bihar", "Chhattisgarh",
  "Goa", "Gujarat", "Haryana", "Himachal Pradesh", "Jharkhand", "Karnataka",
  "Kerala", "Madhya Pradesh", "Maharashtra", "Manipur", "Meghalaya", "Mizoram",
  "Nagaland", "Odisha", "Punjab", "Rajasthan", "Sikkim", "Tamil Nadu",
  "Telangana", "Tripura", "Uttar Pradesh", "Uttarakhand", "West Bengal",
  "Jammu and Kashmir"
];

export default function ApplyForm() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [job, setJob] = useState(null);
  const [loading, setLoading] = useState(false);

  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    skillset: "",
    state: "",
    city: "",
    pincode: "",
    address: "",
    project: "",
    tenth: "",
    tenthSchool: "",
    diploma: "",
    diplomaCollege: "",
    diplomaStream: "",
    graduation: "",
    graduationCollege: "",
    graduationStream: "",
    postGraduation: "",
    postGraduationCollege: "",
    postGraduationStream: "",
    resumeUrl: "",
  });

  useEffect(() => {
    fetchJobDetails();
  }, [id]);

  const fetchJobDetails = async () => {
    try {
      const response = await axios.get("http://localhost:5000/api/jobs");
      const foundJob = response.data.find((j) => j._id === id);
      if (foundJob) setJob(foundJob);
    } catch (err) {
      console.error("Error fetching job:", err);
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  // ✅ NEW: handle PDF resume upload
  const handleResumeUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const formDataFile = new FormData();
    formDataFile.append("resume", file);

    try {
      setLoading(true);
      const res = await axios.post("http://localhost:5000/api/upload-resume", formDataFile, {
        headers: { "Content-Type": "multipart/form-data" },
      });

      const extracted = res.data; // { skillset, project, internships }
      alert("Resume uploaded successfully! Extracted details will be filled automatically.");

      setFormData((prev) => ({
        ...prev,
        skillset: extracted.skillset || prev.skillset,
        project: extracted.project || prev.project,
        resumeUrl: extracted.resumeUrl || "",
      }));
    } catch (err) {
      console.error("Error uploading resume:", err);
      alert("Failed to process resume. Please fill details manually.");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!formData.name || !formData.email || !formData.phone || !formData.skillset ||
      !formData.state || !formData.city || !formData.pincode || !formData.address ||
      !formData.tenth || !formData.tenthSchool || !formData.diploma ||
      !formData.diplomaCollege || !formData.diplomaStream || !formData.graduation ||
      !formData.graduationCollege || !formData.graduationStream ||
      !formData.project) {
      alert("Please fill all required fields marked with *!");
      return;
    }

    const applicationData = {
      name: formData.name,
      email: formData.email,
      phone: formData.phone,
      skillset: formData.skillset,
      resumeUrl: formData.resumeUrl || "Uploaded",
      jobId: id,
      jobTitle: job?.title || "NA",
      location: `${formData.city}, ${formData.state}`,
      pincode: formData.pincode,
      address: formData.address,
      project: formData.project,
      academic: {
        tenth: { score: formData.tenth, school: formData.tenthSchool },
        diploma: { score: formData.diploma, college: formData.diplomaCollege, stream: formData.diplomaStream },
        graduation: { score: formData.graduation, college: formData.graduationCollege, stream: formData.graduationStream },
        postGraduation: { score: formData.postGraduation, college: formData.postGraduationCollege, stream: formData.postGraduationStream },
      },
    };

    try {
      setLoading(true);
      await axios.post("http://localhost:5000/api/applications", applicationData);
      alert("Application submitted successfully!");
      navigate("/");
    } catch (err) {
      console.error("Error submitting application:", err);
      alert("Failed to submit application. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  if (!job) {
    return (
      <div style={styles.loadingContainer}>
        <div style={styles.loader}></div>
        <p>Loading application form...</p>
      </div>
    );
  }

  return (
    <div style={styles.page}>
      <div style={styles.container}>
        <div style={styles.header}>
          <button style={styles.backBtn} onClick={() => navigate(`/job/${id}`)}>
            ← Back to Job Details
          </button>
        </div>

        <div style={styles.formWrapper}>
          {/* Sidebar remains same */}
          <div style={styles.sidebar}>
            <div style={styles.jobInfoCard}>
              <div style={styles.badge}>Now Hiring</div>
              <h3 style={styles.jobTitle}>{job.title}</h3>
              <p style={styles.jobRole}>{job.role}</p>
              <div style={styles.divider}></div>
              <div style={styles.infoSection}>
                <h4 style={styles.sidebarTitle}>Position Details</h4>
                <div style={styles.detailItem}><span style={styles.detailLabel}>Location</span><span style={styles.detailValue}>{job.location}</span></div>
                <div style={styles.detailItem}><span style={styles.detailLabel}>Experience</span><span style={styles.detailValue}>{job.experience}</span></div>
                <div style={styles.detailItem}><span style={styles.detailLabel}>Salary Range</span><span style={styles.detailValue}>{job.ctc}</span></div>
                <div style={styles.detailItem}><span style={styles.detailLabel}>Job Type</span><span style={styles.detailValue}>Full Time</span></div>
              </div>
              <div style={styles.divider}></div>
              <div style={styles.infoSection}>
                <h4 style={styles.sidebarTitle}>Required Skills</h4>
                <div style={styles.skillsList}>
                  {job.skillset.split(",").map((skill, i) => (
                    <span key={i} style={styles.skillBadge}>{skill.trim()}</span>
                  ))}
                </div>
              </div>
            </div>
          </div>

          {/* Form Section */}
          <div style={styles.formContainer}>
            <h2 style={styles.formTitle}>Apply for this Position</h2>
            <form onSubmit={handleSubmit} style={styles.form}>

              {/* Personal Info */}
              <div style={styles.inputGroup}>
                <label style={styles.label}>Full Name *</label>
                <input type="text" name="name" value={formData.name} onChange={handleChange} style={styles.input} required />
              </div>

              <div style={styles.inputRow}>
                <div style={styles.inputGroup}>
                  <label style={styles.label}>Email *</label>
                  <input type="email" name="email" value={formData.email} onChange={handleChange} style={styles.input} required />
                </div>
                <div style={styles.inputGroup}>
                  <label style={styles.label}>Phone Number *</label>
                  <input type="tel" name="phone" value={formData.phone} onChange={handleChange} style={styles.input} required />
                </div>
              </div>

              <div style={styles.inputGroup}>
                <label style={styles.label}>Your Skillset *</label>
                <input type="text" name="skillset" value={formData.skillset} onChange={handleChange} style={styles.input} placeholder="e.g., React, Node.js" required />
              </div>

              {/* ✅ Replace Resume URL field */}
              <div style={styles.inputGroup}>
                <label style={styles.label}>Upload Resume (PDF) *</label>
                <input
                  type="file"
                  name="resume"
                  accept="application/pdf"
                  onChange={handleResumeUpload}
                  style={styles.input}
                  required
                />
                <small style={styles.helpText}>Upload your resume (PDF only). Details will be auto-filled.</small>
              </div>

              <div style={styles.inputGroup}>
                <label style={styles.label}>Project Details *</label>
                <textarea name="project" value={formData.project} onChange={handleChange} style={{...styles.input, minHeight: "100px"}} required />
              </div>

              <button type="submit" style={styles.submitBtn} disabled={loading}>
                {loading ? "Submitting..." : "Submit Application"}
              </button>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
}




const styles = {
  page: { minHeight: "100vh", background: "#f5f7fb", padding: "40px 20px" },
  container: { maxWidth: "1400px", margin: "0 auto" },
  header: { marginBottom: "20px" },
  backBtn: { background: "#fff", border: "1px solid #e2e8f0", padding: "10px 20px", borderRadius: "8px", cursor: "pointer", fontSize: "14px", fontWeight: "500", color: "#475569" },
  formWrapper: { display: "grid", gridTemplateColumns: "350px 1fr", gap: "30px" },
  sidebar: { position: "sticky", top: "20px", height: "fit-content" },
  jobInfoCard: { background: "#fff", borderRadius: "12px", padding: "24px", boxShadow: "0 2px 12px rgba(0,0,0,0.08)" },
  badge: { background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)", color: "#fff", padding: "4px 12px", borderRadius: "20px", fontSize: "11px", fontWeight: "600", textTransform: "uppercase", letterSpacing: "0.5px", display: "inline-block", marginBottom: "12px" },
  jobTitle: { fontSize: "22px", fontWeight: "700", color: "#1e293b", marginBottom: "4px", lineHeight: "1.3" },
  jobRole: { fontSize: "14px", color: "#64748b", marginBottom: "16px" },
  divider: { height: "1px", background: "#e2e8f0", margin: "20px 0" },
  infoSection: { marginBottom: "4px" },
  sidebarTitle: { fontSize: "13px", fontWeight: "700", color: "#1e293b", marginBottom: "14px", textTransform: "uppercase", letterSpacing: "0.5px" },
  detailItem: { display: "flex", justifyContent: "space-between", alignItems: "center", padding: "10px 0", borderBottom: "1px solid #f1f5f9" },
  detailLabel: { fontSize: "13px", color: "#64748b", fontWeight: "500" },
  detailValue: { fontSize: "13px", color: "#1e293b", fontWeight: "600" },
  skillsList: { display: "flex", flexWrap: "wrap", gap: "8px" },
  skillBadge: { background: "#dbeafe", color: "#1e40af", padding: "6px 12px", borderRadius: "6px", fontSize: "12px", fontWeight: "600" },
  responsibilitiesList: { margin: 0, paddingLeft: "20px", color: "#111c2bff" },
  responsibilityItem: { fontSize: "13px", marginBottom: "8px", lineHeight: "1.5" },
  benefitsList: { display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" },
  benefitItem: { display: "flex", flexDirection: "column", alignItems: "center", textAlign: "center", padding: "12px", background: "#f8fafc", borderRadius: "8px" },
  benefitIcon: { fontSize: "24px", marginBottom: "6px" },
  benefitText: { fontSize: "11px", fontWeight: "600", color: "#475569" },
  helpBox: { background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)", padding: "20px", borderRadius: "10px", marginTop: "20px" },
  helpTitle: { fontSize: "14px", fontWeight: "700", color: "#fff", marginBottom: "8px", margin: 0 },
  helpText: { fontSize: "12px", color: "rgba(255,255,255,0.9)", marginBottom: "12px", lineHeight: "1.5" },
  helpLink: { fontSize: "13px", color: "#fff", fontWeight: "600", textDecoration: "none", display: "inline-block", borderBottom: "2px solid rgba(255,255,255,0.5)" },
  formContainer: { background: "#fff", borderRadius: "12px", padding: "32px", boxShadow: "0 2px 12px rgba(0,0,0,0.08)" },
  formTitle: { fontSize: "28px", fontWeight: "700", color: "#1e293b", marginBottom: "8px" },
  formSubtitle: { fontSize: "15px", color: "#64748b", marginBottom: "32px" },
  form: { display: "flex", flexDirection: "column", gap: "20px" },
