  label: { fontSize: "14px", fontWeight: "600", color: "#374151", marginBottom: "6px" },
  required: { color: "#ef4444" },
  input: { padding: "10px 14px", border: "1px solid #cbd5e1", borderRadius: "8px", fontSize: "14px", color: "#1e293b", outline: "none", transition: "border-color 0.2s" },
