  academicSection: { background: "#f8fafc", padding: "20px", borderRadius: "8px", marginBottom: "16px" },
  academicTitle: { fontSize: "15px", fontWeight: "600", color: "#475569", marginBottom: "12px" },
  submitBtn: { background: "#2563eb", color: "#fff", border: "none", padding: "14px 32px", borderRadius: "8px", fontSize: "16px", fontWeight: "600", cursor: "pointer", marginTop: "16px" },
  loadingContainer: { display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", height: "100vh", background: "#f5f7fb" },
  loader: { width: "50px", height: "50px", border: "5px solid #e2e8f0", borderTop: "5px solid #2563eb", borderRadius: "50%", animation: "spin 1s linear infinite" },
};
